# Synonym → slug lookup table (built at import time)
_SYNONYM_INDEX: dict[str, str] = {}
for _slug, _profile in INDUSTRY_PROFILES.items():
    _SYNONYM_INDEX[_profile["display_name"].lower()] = _slug
    for _syn in _profile["synonyms"]:
        _SYNONYM_INDEX[_syn.lower()] = _slug


def resolve_industry(raw: str) -> str | None:
    """Resolve a raw industry string to a canonical slug.

    Checks exact slug match, then display name, then synonyms.
    Returns None if no match found.
    """
    key = raw.strip().lower()
    if key in INDUSTRY_PROFILES:
        return key
    return _SYNONYM_INDEX.get(key)


def get_profile(slug: str) -> dict | None:
    """Get a full industry profile by slug. Returns None if not found."""
    return INDUSTRY_PROFILES.get(slug)
